select id, '1.0.0', 'published', $m_snake${"key":"snake","version":"1.0.0","runtime":1,"family":"arcade","name":"Snake","emoji":"🐍","short":"Snake","summary":"Steer to the food and grow longer, without running into a wall, a rock or yourself.","view":{"width":450,"height":800},"actions":{"up":["swipe-up","ArrowUp","KeyW"],"down":["swipe-down","ArrowDown","KeyS"],"left":["swipe-left","ArrowLeft","KeyA"],"right":["swipe-right","ArrowRight","KeyD"]},"params":{"type":"object","properties":{"grid":{"type":"integer","enum":[10,14,18],"default":14,"title":"Board","x-labels":{"10":"Small","14":"Medium","18":"Large"}},"speed":{"type":"number","minimum":3,"maximum":12,"default":6,"title":"Speed (moves a second)","x-step":0.5,"x-live":true},"speedUp":{"type":"number","minimum":0,"maximum":0.4,"default":0.1,"title":"Faster with each bite","x-step":0.02,"x-live":true},"growth":{"type":"integer","minimum":1,"maximum":4,"default":1,"title":"Growth per bite"},"rocks":{"type":"integer","minimum":0,"maximum":10,"default":0,"title":"Rocks"},"wrap":{"type":"boolean","default":false,"title":"Go through the walls","x-live":true},"lives":{"type":"integer","minimum":1,"maximum":5,"default":3,"title":"Lives"}}},"slots":{"player":{"kind":"sprite","role":"player","title":"Head"},"collectible":{"kind":"sprite","role":"collectible","title":"Food"},"hazard":{"kind":"sprite","role":"hazard","title":"Rock"},"music":{"kind":"music","role":"bgm","optional":true,"title":"Music"}},"vars":["score","time","length","eaten","lives"],"rules":{"win":"eaten >= 20","lose":"lives <= 0"},"rulePresets":{"win":[{"label":"Eat 20","value":"eaten >= 20"},{"label":"Grow to 40","value":"length >= 40"},{"label":"Score 1,000","value":"score >= 1000"},{"label":"Endless","value":null}],"lose":[{"label":"Out of lives","value":"lives <= 0"},{"label":"60 seconds","value":"time >= 60"},{"label":"Out of lives or 90 s","value":"lives <= 0 || time >= 90"}]}}$m_snake$::jsonb, now() from public.mechanics where key = 'snake'
on conflict (mechanic_id, semver) do update set manifest = excluded.manifest;
update public.mechanics m set latest_version_id = v.id from public.mechanic_versions v
 where m.key = 'snake' and v.mechanic_id = m.id and v.semver = '1.0.0';

